def main():
    assert set(P.keys()) == set(CASES), f"预测字典与本批不一致: 缺={set(CASES)-set(P)}, 多={set(P)-set(CASES)}"
    for cid in CASES:
        rec = {"case_id": cid, **P[cid]}
        (OUT / f"{cid}.json").write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
    # 回读自验
    written = 0
    cm = ru = dp = 0
    for cid in CASES:
        fp = OUT / f"{cid}.json"
        assert fp.exists(), f"缺文件 {cid}"
        d = json.loads(fp.read_text(encoding="utf-8"))
        assert d["case_id"] == cid, f"case_id与文件名不对位 {cid}"
        for f in ("prediction_text", "basis", "confidence", "trigger"):
            assert f in d and d[f] not in (None, ""), f"{cid} 字段缺失 {f}"
        assert isinstance(d["confidence"], (int, float)) and 0 <= d["confidence"] <= 1
        t = d["trigger"]
        for b in ("changed_main", "reserve_used", "disputed"):
            assert isinstance(t[b], bool), f"{cid} trigger.{b} 非布尔"
        assert isinstance(t["reason"], str)
        written += 1
        cm += t["changed_main"]; ru += t["reserve_used"]; dp += t["disputed"]
    assert written == len(CASES) == 20, f"写出数 {written} != 本批例数 {len(CASES)}"
    print(f"OK batch=B16 cases={len(CASES)} written={written}")
    print(f"trigger counts: changed_main={cm} reserve_used={ru} disputed={dp}")

if __name__ == "__main__":
    main()
